    my $resolver = Net::DNS::Resolver->new(
        nameservers => ['127.0.0.1'],
        port => 47302,
        recurse => 1,
        udp_timeout => 2,
    );

    my $reply = $resolver->query($query, 'A');

    if ($reply) {
        print "DNS query successful\n";
        foreach my $rr ($reply->answer) {
            print "Answer: ", $rr->string, "\n";
