            0x0001,    # QDCOUNT = 1
            0x0000,    # ANCOUNT = 0
            0x0000,    # NSCOUNT = 0
            0x0000     # ARCOUNT = 0
        );

        # Add the query name
        foreach my $part (split(/\./, $query)) {
            $dns_query .= pack('C', length($part)) . $part;
        }
        $dns_query .= pack('C', 0);  # Null terminator

        # Query type A (1) and class IN (1)
        $dns_query .= pack('n2', 0x0001, 0x0001);

        $socket->send($dns_query);

        my $response;
        $socket->recv($response, 512);

        if ($response) {
