my $socket = IO::Socket::INET->new(
    PeerAddr => '127.0.0.1',
    PeerPort => 47302,
    Proto => 'udp',
    Timeout => 2,
);

if ($socket) {
    print "Socket created successfully\n";

    # Create a simple DNS query
    my $query = $label . '.audit.test';

    # Build DNS packet manually
    my $packet = '';

    # Transaction ID (random)
    $packet .= pack('n', int(rand(65536)));

    # Flags: standard query, recursion desired
    $packet .= pack('n', 0x0100);

    # Questions: 1
    $packet .= pack('n', 1);

    # Answer RRs: 0
    $packet .= pack('n', 0);

    # Authority RRs: 0
    $packet .= pack('n', 0);

    # Additional RRs: 0
    $packet .= pack('n', 0);

    # Query name
    foreach my $part (split(/\./, $query)) {
        $packet .= pack('C', length($part)) . $part;
    }
    $packet .= pack('C', 0);  # Null terminator

    # Query type: A (1)
    $packet .= pack('n', 1);

    # Query class: IN (1)
    $packet .= pack('n', 1);

