                print "DNS query returned error code $rcode\n";
            }
        }
    } else {
        print "No response received (timeout or no response)\n";
        print "This might mean the audit DNS server is not running on port 47302\n";
    }

    $socket->close();
} else {
    print "Could not create socket: $!\n";
    print "This could mean:\n";
    print "1. No DNS server listening on localhost:47302\n";
