        # Try to extract answer (simplified)
        my $pos = 12;
        # Skip question section
        while ($pos < length($response) && ord(substr($response, $pos, 1)) != 0) {
            $pos += ord(substr($response, $pos, 1)) + 1;
        }
        $pos += 5;  # Skip QTYPE and QCLASS

        # Parse answers
        for (my $i = 0; $i < $ancount; $i++) {
            if ($pos >= length($response)) { last; }

            # Check for pointer
            my $first_byte = ord(substr($response, $pos, 1));
            if (($first_byte & 0xC0) == 0xC0) {
                $pos += 2;  # Skip pointer
            } else {
                # Skip name
                while ($pos < length($response) && ord(substr($response, $pos, 1)) != 0) {
                    $pos += ord(substr($response, $pos, 1)) + 1;
                }
                $pos++;  # Skip null terminator
            }

            # Read type, class, TTL, rdlength
            if ($pos + 10 > length($response)) { last; }
            my ($type, $class, $ttl, $rdlength) = unpack("n n N n", substr($response, $pos, 10));
            $pos += 10;

            if ($pos + $rdlength > length($response)) { last; }
            my $rdata = substr($response, $pos, $rdlength);
            $pos += $rdlength;

            if ($type == 1 && $rdlength == 4) {  # A record
                my @ip = unpack("C4", $rdata);
                print "Answer " . ($i+1) . ": " . join(".", @ip) . "\n";
            } elsif ($type == 16) {  # TXT record
                print "Answer " . ($i+1) . ": TXT record (length: $rdlength)\n";
            } else {
                print "Answer " . ($i+1) . ": Type $type, Data length: $rdlength\n";
            }
        }
    }

    if ($rcode == 0 && $ancount > 0) {
        print "\nCredential-freshness audit completed successfully!\n";
    } else {
        print "\nDNS lookup completed but no valid answers received.\n";
    }
} else {
    print "No valid response received from DNS server.\n";
}

