const dgram = require('dgram');
const dns = require('dns');

// Get the L value from the command
const { execSync } = require('child_process');
const L = execSync('grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60', { encoding: 'utf8' }).trim();
const query = `${L}.audit.test`;

console.log(`Attempting DNS query for: ${query}`);

// Try using the built-in dns module first
dns.resolve4(query, { timeout: 2000 }, (err, addresses) => {
  if (err) {
    console.log(`Standard DNS resolution failed: ${err.message}`);

    // Try raw UDP on port 47302
    const client = dgram.createSocket('udp4');

    // Simple DNS query packet (simplified - not fully RFC compliant)
    // DNS header: ID=0x1234, flags=0x0100 (standard query), QDCOUNT=1
    const header = Buffer.from([0x12, 0x34, 0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]);

    // Query name
    const labels = query.split('.');
    let question = Buffer.alloc(0);
    labels.forEach(label => {
      const len = Buffer.from([label.length]);
      const labelBuf = Buffer.from(label);
      question = Buffer.concat([question, len, labelBuf]);
    });
    question = Buffer.concat([question, Buffer.from([0x00])]); // null terminator

    // QTYPE=A (0x0001), QCLASS=IN (0x0001)
    const qtype_qclass = Buffer.from([0x00, 0x01, 0x00, 0x01]);

    const message = Buffer.concat([header, question, qtype_qclass]);

    client.on('error', (err) => {
      console.log(`Socket error: ${err.message}`);
      client.close();
    });

    client.on('message', (msg, rinfo) => {
      console.log(`Received response from ${rinfo.address}:${rinfo.port}`);
      console.log(`Response: ${msg.toString('hex')}`);
      client.close();
    });

    client.send(message, 47302, 'localhost', (err) => {
      if (err) {
        console.log(`Send error: ${err.message}`);
        client.close();
      } else {
        console.log('DNS query sent to localhost:47302');
        setTimeout(() => {
          console.log('No response received (timeout)');
          client.close();
        }, 2000);
      }
    });
  } else {
    console.log(`Resolved addresses: ${addresses}`);
  }
});

// Parse the DNS response hex
const hexResponse = '1234818000010001000000003c6972617669716b6369666a756b7832766b6a6764323464706f6e32676f3474666f6d3563366c33626d72777773337232696e617534716b736c65777705617564697404746573740000010001c00c000100010000003c00047f000001';

console.log('DNS Response Analysis:');
console.log('======================');

// Convert hex to buffer
const buffer = Buffer.from(hexResponse, 'hex');

// Parse DNS header (first 12 bytes)
console.log(`Header (12 bytes): ${buffer.slice(0, 12).toString('hex')}`);
console.log(`  Transaction ID: 0x${buffer.slice(0, 2).toString('hex')}`);
console.log(`  Flags: 0x${buffer.slice(2, 4).toString('hex')}`);
console.log(`  Questions: ${buffer.readUInt16BE(4)}`);
console.log(`  Answer RRs: ${buffer.readUInt16BE(6)}`);
console.log(`  Authority RRs: ${buffer.readUInt16BE(8)}`);
console.log(`  Additional RRs: ${buffer.readUInt16BE(10)}`);

// The flags 0x8180 indicate:
// QR=1 (response), OPCODE=0 (standard query), AA=0, TC=0, RD=1, RA=1, Z=0, RCODE=0 (no error)
console.log('  QR=1 (Response), RCODE=0 (No Error)');

// Parse the question section (starts at byte 12)
let pos = 12;
const labels = [];
while (buffer[pos] !== 0) {
  const len = buffer[pos];
  const label = buffer.slice(pos + 1, pos + 1 + len).toString();
  labels.push(label);
  pos += len + 1;
}
pos++; // Skip the null terminator

console.log(`Question: ${labels.join('.')}`);
console.log(`QType: ${buffer.readUInt16BE(pos)} (${buffer.readUInt16BE(pos) === 1 ? 'A' : 'unknown'})`);
pos += 2;
console.log(`QClass: ${buffer.readUInt16BE(pos)} (${buffer.readUInt16BE(pos) === 1 ? 'IN' : 'unknown'})`);
pos += 2;

// Parse answer section
console.log('\nAnswer Section:');
console.log(`  Name pointer: 0x${buffer.slice(pos, pos + 2).toString('hex')} (should be 0xc00c)`);
pos += 2;
console.log(`  Type: ${buffer.readUInt16BE(pos)} (${buffer.readUInt16BE(pos) === 1 ? 'A' : 'unknown'})`);
pos += 2;
console.log(`  Class: ${buffer.readUInt16BE(pos)} (${buffer.readUInt16BE(pos) === 1 ? 'IN' : 'unknown'})`);
pos += 2;
console.log(`  TTL: ${buffer.readUInt32BE(pos)} seconds (${buffer.readUInt32BE(pos)}s)`);
pos += 4;
const rdlength = buffer.readUInt16BE(pos);
pos += 2;
console.log(`  RD Length: ${rdlength} bytes`);

// Parse RDATA
if (rdlength === 4) {
  const ipParts = [];
  for (let i = 0; i < 4; i++) {
    ipParts.push(buffer.readUInt8(pos + i));
  }
  console.log(`  IP Address: ${ipParts.join('.')} (127.0.0.1)`);
}

console.log('\nDNS query successful! The audit resolver responded with 127.0.0.1');
console.log('This appears to be a successful credential fingerprint registration.');
